CREATE POLICY "Admins can upload course photos" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'course-photos' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can update course photos" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'course-photos' AND public.has_role(auth.uid(), 'admin'::app_role)) WITH CHECK (bucket_id = 'course-photos' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can delete course photos" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'course-photos' AND public.has_role(auth.uid(), 'admin'::app_role));
CREATE POLICY "Admins can read course photos" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'course-photos' AND public.has_role(auth.uid(), 'admin'::app_role));